import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Build, Sign and Release","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/releasing.md","filePath":"en/reference/releasing.md","lastUpdated":1795157329000}'),n={name:"en/reference/releasing.md"};function l(r,e,d,o,p,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="build-sign-and-release" tabindex="-1">Build, Sign and Release <a class="header-anchor" href="#build-sign-and-release" aria-label="Permalink to &quot;Build, Sign and Release&quot;">​</a></h1><p>The desktop app is a Tauri application; the server and web bundle ship with the installer. A release has three steps: build, sign, stage.</p><h2 id="_1-build" tabindex="-1">1. Build <a class="header-anchor" href="#_1-build" aria-label="Permalink to &quot;1. Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:build</span></span></code></pre></div><p><code>scripts/build-tauri.mjs</code> prepares the bundled Node runtime, server bundle and web assets, then calls <code>tauri build</code> and copies the NSIS installer into <code>release/</code> at the repository root.</p><p>When signing variables are absent the script warns and produces a normal installer <strong>without auto-update</strong>. It does not create an installer that looks signed but cannot update.</p><h2 id="_2-updater-signing" tabindex="-1">2. Updater signing <a class="header-anchor" href="#_2-updater-signing" aria-label="Permalink to &quot;2. Updater signing&quot;">​</a></h2><p>Auto-update requires all three:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>TAURI_SIGNING_PRIVATE_KEY</code></td><td>Signs updater artifacts; a file path or the key itself</td></tr><tr><td><code>HEARTH_UPDATER_PUBKEY</code></td><td>Public key embedded in the client</td></tr><tr><td><code>HEARTH_UPDATER_ENDPOINT</code></td><td><code>latest.json</code> endpoint the client checks</td></tr></tbody></table><p>With all three, the build script writes a temporary <code>src-tauri/updater.build.json</code>, enables <code>createUpdaterArtifacts</code> and the <code>updater</code> Cargo feature, and produces a <code>.sig</code> file. With any missing, auto-update stays off.</p><p>Keep the private key on the release machine or in CI secrets, never in the repository. The public key is safe to publish.</p><h2 id="_3-stage-release-artifacts" tabindex="-1">3. Stage release artifacts <a class="header-anchor" href="#_3-stage-release-artifacts" aria-label="Permalink to &quot;3. Stage release artifacts&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:prepare</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or reuse an existing installer without rebuilding</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:prepare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-build</span></span></code></pre></div><p>The script writes into <code>release/&lt;version&gt;/</code>:</p><ul><li><code>Hearth_&lt;version&gt;_x64-setup.exe</code>: the Windows installer;</li><li><code>Hearth-&lt;version&gt;-portable.zip</code>: extract, keep <code>resources/</code> beside <code>Hearth.exe</code>, run;</li><li><code>RELEASE_NOTES.md</code>: version, commit list and install notes;</li><li><code>SHA256SUMS.txt</code>: checksums for the installer, portable archive and notes;</li><li><code>latest.json</code> (optional): generated when <code>HEARTH_RELEASE_BASE_URL</code> and a <code>.sig</code> file exist.</li></ul><p>The download URL in <code>latest.json</code> is <code>HEARTH_RELEASE_BASE_URL</code> plus the installer filename, so upload both to the same version directory.</p><h2 id="before-publishing" tabindex="-1">Before publishing <a class="header-anchor" href="#before-publishing" aria-label="Permalink to &quot;Before publishing&quot;">​</a></h2><ul><li><code>npm run typecheck &amp;&amp; npm test &amp;&amp; npm run build &amp;&amp; npm run docs:build</code></li><li><code>cargo check --manifest-path apps/desktop-tauri/src-tauri/Cargo.toml --features updater</code></li><li>install, launch and uninstall once on a clean machine;</li><li>verify downloads against <code>SHA256SUMS.txt</code>;</li><li>verify one auto-update from an older build.</li></ul><p>The release script never tags, pushes or uploads by itself. Those steps need a human decision.</p>`,19)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
